import java.util.Scanner;

public class Words {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length = scanner.nextInt();
        String strInput = scanner.next();
        char[] charsArray = strInput.toCharArray();
        int[] segmentCountsArray = new int[length];
        int totalWordsDetected = 0;
        int segmentIndex = 0;
        for (int i = 0; i < length; i++) {
            segmentCountsArray[i] = 0;
        }
        int mode = 0;
        if (charsArray[0] == '_') {
            mode = 0;
        } else if (charsArray[0] == '(') {
            mode = 1;
        }
        for (int i = 0; i < length; i++) {
            if (mode == 0) {
                if (charsArray[i] == '_') {
                    segmentIndex++;
                } else {
                    if (charsArray[i] != '(') {
                        segmentCountsArray[segmentIndex]++;
                    } else if (charsArray[i] == '(') {
                        mode = 1;
                    } else if (charsArray[i] == ')') {
                        mode = 0;
                    }
                }
            } else {
                if (charsArray[i] == ')') {
                    mode = 0;
                    segmentIndex++;
                } else if (i > 0) {
                    if (charsArray[i - 1] == '(' || charsArray[i - 1] == '_') {
                        if (charsArray[i] != '_' && charsArray[i] != '(') {
                            totalWordsDetected++;
                        }
                    }
                }
            }
        }
        // Bubble sort in descending order
        for (int i = 0; i < length; i++) {
            for (int j = i; j > 0; j--) {
                if (segmentCountsArray[j] > segmentCountsArray[j - 1]) {
                    int tempVal = segmentCountsArray[j];
                    segmentCountsArray[j] = segmentCountsArray[j - 1];
                    segmentCountsArray[j - 1] = tempVal;
                }
            }
        }
        System.out.println(segmentCountsArray[0]);
        System.out.println(totalWordsDetected);
    }
}
